#include <cctype>
#include <future>
#include <thread>
#include <vector>

namespace parallel_letter_frequency {

namespace {

std::map<char, int> count_text(std::string_view text) {
    std::map<char, int> counts;
    for (unsigned char ch : text) {
        if (std::isalpha(ch)) {
            char const lower = static_cast<char>(std::tolower(ch));
            ++counts[lower];
        }
    }
    return counts;
}

}  // namespace

std::map<char, int> frequency(std::vector<std::string_view> const& texts) {
    std::map<char, int> total;

    if (texts.empty()) {
        return total;
    }

    std::vector<std::future<std::map<char, int>>> futures;
    futures.reserve(texts.size());

    for (auto const& text : texts) {
        futures.push_back(
            std::async(std::launch::async, count_text, text));
    }

    for (auto& fut : futures) {
        auto const counts = fut.get();
        for (auto const& [letter, count] : counts) {
            total[letter] += count;
        }
    }

    return total;
}

}  // namespace parallel_letter_frequency
"}

